on conflict(provider_entity) do update set
  source_id=coalesce(excluded.source_id,public.cooperative_provider_registry.source_id),
  aliases=excluded.aliases,registry_mode=excluded.registry_mode,active=true,
  notes=coalesce(excluded.notes,public.cooperative_provider_registry.notes),updated_at=now();

select cron.alter_job(29, active => false);
select cron.alter_job(30, active => false);

update app_private.coop_provider_index_requests
set processed_at=coalesce(processed_at,now()),
    error=case when processed_at is null then 'disabled_replaced_by_global_portal_registry' else error end
where processed_at is null;
